const CONVERSATION_PINNED_EVENT = 'conversationPinned';

/** Announces completed conversation pin writes to every attached window. */
class ConversationPinEvents extends EventTarget {
    subscribe(listener) {
        if (typeof listener !== 'function') throw new Error('Conversation pin subscription requires a listener');
        const handlePinned = (event) => {
            try {
                listener(event.detail);
            } catch (error) {
                console.error('Conversation pin listener failed', error);
            }
        };
        this.addEventListener(CONVERSATION_PINNED_EVENT, handlePinned);

        return () => this.removeEventListener(CONVERSATION_PINNED_EVENT, handlePinned);
    }

    emit(event) {
        this.dispatchEvent(new CustomEvent(CONVERSATION_PINNED_EVENT, { detail: event }));
    }
}

