        conversationId ? dataService.agents.subscribeConversationPinned(conversationId, listener) : () => undefined
    ), [conversationId])
    const getSnapshot = useCallback(() => (
        conversationId ? dataService.agents.getConversationPinnedSnapshot(conversationId) ?? fallbackPinned : false
    ), [conversationId, fallbackPinned])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

