import { getElectronActionBridge, type ActionConversationPinnedEvent } from '../../data/electron_action_bridge'

const PINNED_CONVERSATIONS_CHANGED_EVENT = 'pinned-conversations'

export function conversationPinnedEvent(conversationId: string) {
    return `conversation-pinned-${conversationId}`
}

interface ConversationPinServiceDependencies {
    updateProjectConfig(pinnedConversationIds: string[]): void
}

/** Owns the current project's pinned conversation identities independently of conversation records. */
export class ConversationPinService {
    private cleanup: (() => void) | null = null
    private readonly dependencies: ConversationPinServiceDependencies
    private readonly events = new EventTarget()
    private pinnedConversationIds: string[] = []

    constructor(dependencies: ConversationPinServiceDependencies) {
        this.dependencies = dependencies
    }

    readonly getSnapshot = () => this.pinnedConversationIds

    isPinned(conversationId: string) {
        return this.pinnedConversationIds.includes(conversationId)
    }

    readonly subscribe = (listener: () => void) => {
        this.events.addEventListener(PINNED_CONVERSATIONS_CHANGED_EVENT, listener)

        return () => this.events.removeEventListener(PINNED_CONVERSATIONS_CHANGED_EVENT, listener)
    }

    subscribeConversation(conversationId: string, listener: () => void) {
        const eventType = conversationPinnedEvent(conversationId)
        this.events.addEventListener(eventType, listener)

        return () => this.events.removeEventListener(eventType, listener)
    }

    start() {
        if (this.cleanup) return
        const bridge = getElectronActionBridge()
        if (!bridge?.onActionConversationPinned) return

        this.cleanup = bridge.onActionConversationPinned((event) => this.applyEvent(event))
    }

    reset(pinnedConversationIds: string[] = []) {
        this.replace(pinnedConversationIds, false)
    }

    stop() {
        this.cleanup?.()
        this.cleanup = null
    }

    /** Persists before publishing, so failures leave the last confirmed list intact. */
    async setPinned(conversationId: string, pinned: boolean) {
        if (!conversationId) throw new Error('Missing conversation identity')
        const bridge = getElectronActionBridge()
        if (!bridge?.updateActionConversationPinned) throw new Error('Updating conversation pins requires Electron')

        const pinnedConversationIds = await bridge.updateActionConversationPinned(conversationId, pinned)
        this.replace(pinnedConversationIds, true)
    }

    private applyEvent({ conversationId, pinned }: ActionConversationPinnedEvent) {
        const pinnedConversationIds = pinned
            ? [...this.pinnedConversationIds.filter((id) => id !== conversationId), conversationId]
            : this.pinnedConversationIds.filter((id) => id !== conversationId)
        this.replace(pinnedConversationIds, true)
    }

    private replace(pinnedConversationIds: string[], updateProjectConfig: boolean) {
        if (!Array.isArray(pinnedConversationIds)
            || !pinnedConversationIds.every((conversationId) => typeof conversationId === 'string' && conversationId.length > 0)) {
            throw new Error('Invalid pinned conversation identities')
        }
        if (new Set(pinnedConversationIds).size !== pinnedConversationIds.length) {
            throw new Error('Duplicate pinned conversation identities')
        }
        const previous = this.pinnedConversationIds
        if (previous.length === pinnedConversationIds.length
            && previous.every((conversationId, index) => conversationId === pinnedConversationIds[index])) return

        this.pinnedConversationIds = [...pinnedConversationIds]
        if (updateProjectConfig) this.dependencies.updateProjectConfig(this.pinnedConversationIds)
        const changedConversationIds = new Set([...previous, ...this.pinnedConversationIds])
        for (const conversationId of changedConversationIds) {
            if (previous.includes(conversationId) === this.pinnedConversationIds.includes(conversationId)) continue
            this.events.dispatchEvent(new Event(conversationPinnedEvent(conversationId)))
        }
        this.events.dispatchEvent(new Event(PINNED_CONVERSATIONS_CHANGED_EVENT))
    }
}

